+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const def = LANGUAGES.includes(fallback) ? fallback : LANGUAGES[0];
+  if (typeof header !== "string" || !header.trim()) return def;
+  const candidates = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    if (!rawTag) continue;
+    let q = 1;
+    for (const param of params) {
+      const [k, v] = param.split("=");
+      if (k && k.trim().toLowerCase() === "q") {
+        q = v !== undefined && v.trim() !== "" ? Number(v.trim()) : NaN;
+      }
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) continue;
+    const lang = rawTag.trim().toLowerCase().split(/[-_]/)[0];
+    if (LANGUAGES.includes(lang)) candidates.push({ lang, q });
+  }
+  candidates.sort((a, b) => b.q - a.q);
+  return candidates[0]?.lang ?? def;
+}
